package com.cni.session; import com.cni.casefile.InvestigationCase; import com.cni.user.AppUser; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="investigation_sessions",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","case_id","status"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class InvestigationSession{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id",nullable=false)private AppUser user;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="case_id",nullable=false)private InvestigationCase investigationCase;@Column(nullable=false,length=16)private String status;@Column(columnDefinition="TEXT")private String stateJson;@Column(name="started_at",nullable=false)private Instant startedAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;}
